import {CALLS,PROGRAMS,FREQUENCIES,FLAG_NAMES,STORAGE_KEY,initialState,readSave,answerCall,choose,broadcast,tune,repair,next,effectLabel,choiceRequirement,getEnding} from './game.js';
import {RadioAudio} from './audio.js';
import {createStudio} from './scene.js';
const $=id=>document.getElementById(id);
const paths={moon:'M20.9 13A9 9 0 0 1 11 3.1 9 9 0 1 0 20.9 13Z',radio:'M4 8h16v12H4z M7 5l11-3 M7 12h5 M7 16h5 M17 12v5',signal:'M5 19v-3 M10 19V12 M15 19V8 M20 19V4',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2Z M9 3v16 M15 5v16',book:'M4 3h12a3 3 0 0 1 3 3v15H6a3 3 0 0 1-3-3V5a2 2 0 0 1 2-2 M3 17h16 M7 7h8 M7 11h6',cloud:'M5 17a4 4 0 0 1-.7-7.9A6 6 0 0 1 16 7.7a4.6 4.6 0 1 1 1.5 9.3 M8 20l-1 2 M13 20l-1 2 M18 20l-1 2',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',battery:'M3 7h16v10H3z M22 10v4 M7 10v4 M11 10v4 M15 10v4',save:'M5 3h12l4 4v14H3V3z M7 3v6h9V3 M7 21v-7h10v7',mic:'M9 6a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0Z M5 10v3a7 7 0 0 0 14 0v-3 M12 20v3 M8 23h8',disc:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M14 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0 M6 12a6 6 0 0 1 6-6 M18 12a6 6 0 0 1-6 6',tape:'M3 5h18v14H3z M7 15l2-5h6l2 5Z M8 8h.1 M16 8h.1 M6 16h12',phone:'M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6 19.8 19.8 0 0 1-3.1-8.7A2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7c.1 1 .3 2 .7 2.9a2 2 0 0 1-.5 2.1L8 10a16 16 0 0 0 6 6l1.3-1.3a2 2 0 0 1 2.1-.5c.9.4 1.9.6 2.9.7a2 2 0 0 1 1.7 2Z',mouse:'M7 8a5 5 0 0 1 10 0v8a5 5 0 0 1-10 0Z M12 3v6',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 11v6 M12 7h.01',help:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M9.1 9a3 3 0 0 1 5.8 1c0 2-3 3-3 3 M12 17h.01',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3l-1 3-3 1-2 3 2 2-1 3 2 3 3-1 3 3 3-2 3 1 2-3-1-3 2-2-2-3-3-1-1-3Z',close:'m6 6 12 12 M6 18 18 6','volume-off':'M11 5 6 9H3v6h3l5 4Z M16 9l5 6 M21 9l-5 6',volume:'M11 5 6 9H3v6h3l5 4Z M15 8a6 6 0 0 1 0 8 M18 5a10 10 0 0 1 0 14',check:'m5 12 4 4L19 6',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',tool:'M14 6a5 5 0 0 0-6 6L2 18l4 4 6-6a5 5 0 0 0 6-6l-4 2-3-3Z',sun:'M12 3V1 M12 23v-2 M3 12H1 M23 12h-2 M5 5 3 3 M21 21l-2-2 M5 19l-2 2 M21 3l-2 2 M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.radio}"/></svg>`;
function icons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
const esc=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storage;try{storage=window.localStorage;}catch{storage={getItem:()=>null,setItem:()=>{throw Error('blocked')}};}let state=readSave(storage),audio=new RadioAudio(),studio=null,activeView='studio',returnFocus=null,toastTimer,frequency=89.7,repairSteps=[];audio.set(state.muted,state.volume);
function persist(){try{storage.setItem(STORAGE_KEY,JSON.stringify(state));$('save-label').textContent='进度已自动保存';}catch{$('save-label').textContent='浏览器未允许保存';}}
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,5200);}
function currentCall(){
 const c={...CALLS[state.turn]};
 if(state.turn===3&&state.flags.includes('EVAC_DONE')){c.preview='「学校里的名字点齐了。\n你的声音，把大家带到了这里。」';c.text='我们已经到了北坡学校，下街的人都在。孩子终于不再问收音机会不会睡着。我从店里带来了旧天线和蓄电池。雨还没停，你还需要我们做些什么？';}
 if(state.turn===4){if(state.flags.includes('LOCATION'))c.preview='「你找到三号井了，对吗？\n我还在最上面的台阶等你。」';else if(state.activeProgram!=='music')c.preview='「收音机里，终于有你的声音。\n你能告诉我妈妈吗？」';}
 if(state.turn===5&&state.flags.includes('TRUTH_PUBLIC'))c.text='镇上已经听见林舟那卷录音了。有几位当年的工人也来帮忙。我们到了岔路口，左边是检修门，右边是旧梯子。雨太大，看不清井口。现在，照着你的声音走——你说，我们先走哪一边？';
 return c;
}
function render(){
 const c=currentCall();$('clock').textContent=state.phase==='ended'?'05:42':c.time;$('chapter-label').textContent=state.phase==='ended'?'第一夜 · 天色渐明':state.turn<2?'第一夜 · 雾中的声音':state.turn<4?'第一夜 · 被淹没的往事':'第一夜 · 天亮之前';
 $('listeners').textContent=`${128+Math.round((state.trust-62)*2.5)+state.turn*27} 人正在收听`;
 for(let k of ['trust','signal','power']){$(k+'-bar').style.width=state[k]+'%';$(k+'-value').textContent=state[k];$(k+'-bar').style.background=state[k]<20?'#d18f73':'';}
 $('sound-button').innerHTML=icon(state.muted?'volume-off':'volume');$('sound-button').setAttribute('aria-label',state.muted?'开启声音':'关闭声音');$('sound-button').title=state.muted?'开启声音':'关闭声音';
 $('programs').innerHTML=PROGRAMS.map(p=>`<button class="program-card ${state.selected===p.id?'selected':''}" data-program="${p.id}" aria-pressed="${state.selected===p.id}" ${state.phase==='ended'?'disabled':''}><span class="program-cover">${icon(p.icon)}</span><span><h3>${p.title}</h3><small>${p.description}</small><span class="program-kind">${p.kind}</span></span><i class="selection-dot"></i></button>`).join('');
 const p=PROGRAMS.find(p=>p.id===state.selected);$('broadcast-button').disabled=state.broadcasted||state.phase==='ended'||state.power<Math.abs(p.effect[2]);$('broadcast-button').querySelector('span:nth-child(2)').textContent=state.phase==='ended'?'本夜已结束':state.broadcasted?'本期已播出':'开始广播';
 $('broadcast-status').textContent=state.broadcasted?(PROGRAMS.find(p=>p.id===state.activeProgram)?.title||'本期广播已完成'):state.phase==='ended'?'感谢收听，晚安':'等待你的声音';
 $('broadcast-hint').textContent=state.broadcasted?'你的声音已经抵达小镇。接听下一通来电，继续这一夜。':state.selected==='truth'&&!state.flags.includes('PROOF')?'尚未取得原始证据：本次只播寻人进展。 '+effectLabel(p.effect):state.selected==='evac'?`播出后需信任 ${state.flags.includes('EVAC_PREP')?30:40}、信号 20。 ${effectLabel(p.effect)}`:effectLabel(p.effect)+' · 每通来电可播出一期节目';
 let content=`<div class="call-top"><span>INCOMING CALL ${String(state.turn+1).padStart(2,'0')} / 06</span><span class="incoming-state"><i></i>${state.phase==='ringing'?'来电等待中':state.phase==='connected'?'通话中':'线路已记录'}</span></div><div class="caller"><span class="caller-avatar">${c.initial}</span><div><h3>${c.name}</h3><small>${c.place}</small></div></div>`;
 if(state.phase==='ringing'){content+=`<p class="call-preview">${c.preview}</p><button class="answer-button" data-action="answer">${icon('phone')}接听来电<span style="opacity:.5;margin-left:13px;font:9px monospace">E</span></button><p class="call-foot">接起电话，听听夜晚另一端的故事。</p>`;}
 if(state.phase==='connected'){content+=`<p class="call-preview full">${c.text}</p><div class="choice-list">${c.choices.map((choice,i)=>{let reason=choiceRequirement(state,choice);return `<button class="choice-button" data-choice="${i}" ${reason?'disabled':''}>${choice.label}<small>${reason||effectLabel(choice.effect)}</small></button>`;}).join('')}</div><button class="secondary-button" data-action="read-call" style="width:100%;margin-top:11px">${state.muted?'开启声音并听来电':'听来电语音'}</button>`;}
 if(state.phase==='resolved'){content+=`<p class="call-preview full">${esc(state.result)}</p><div class="call-result">${icon('check')}<span>${state.broadcasted?'本期广播已完成。':'还可以播出一期节目，或直接继续。'}</span></div><button class="answer-button next-call-button" data-action="next">${state.turn===5?icon('sun'):icon('phone')}${state.turn===5?'守候到天亮':'等待下一通来电'}</button>`;}
 if(state.phase==='ended'){let e=getEnding(state);content=`<div class="call-top"><span>THE NIGHT IS OVER</span><span>05:42 AM</span></div><div class="caller"><span class="caller-avatar">☀</span><div><h3>${e.title}</h3><small>这一夜的声音，已被记住。</small></div></div><p class="call-preview">雾港的清晨，从你的频率开始。</p><button class="answer-button" data-action="ending">${icon('book')}查看夜晚回响</button>`;}
 $('call-panel').classList.toggle('connected',state.phase==='connected');$('call-panel').innerHTML=content;studio?.update({turn:state.turn,phase:state.phase,playing:state.activeProgram==='music'});persist();
}
function answer(){if(answerCall(state)){audio.init();audio.click();render();}}
function chooseOption(i){if(choose(state,i)){audio.stopSpeech();audio.success();render();}}
function doBroadcast(){const result=broadcast(state);if(result){audio.init();if(state.selected==='music')audio.music();else{audio.stopMusic();audio.tone(523,.4,.08);}toast(result);render();}else if(state.phase!=='ended')toast(state.broadcasted?'本期已经播出。下一通来电后可再次广播。':'电力不足，请检查备用电路。');}
function nextCall(){if(!next(state))return;audio.stopSpeech();if(state.phase==='ended'){audio.stopMusic();audio.success();render();openEnding();}else{audio.ring();render();toast(`${CALLS[state.turn].time} · 新的来电接入了。`);}}
function setSound(){audio.init();state.muted=!state.muted;audio.set(state.muted,state.volume);if(!state.muted){audio.click();if(state.phase==='ringing')audio.ring();}else audio.stopSpeech();render();}
function modal(title,eyebrow,html){returnFocus=document.activeElement;$('modal-title').textContent=title;$('modal-eyebrow').textContent=eyebrow;$('modal-content').innerHTML=html;$('modal').hidden=false;icons($('modal'));requestAnimationFrame(()=>$('close-modal').focus());}
function closeModal(){$('modal').hidden=true;activeView='studio';document.querySelectorAll('.nav-button').forEach(b=>b.classList.toggle('active',b.dataset.view==='studio'));returnFocus?.focus();}
function selectView(view){activeView=view;document.querySelectorAll('.nav-button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));audio.click();if(view==='studio'){closeModal();studio?.resetView();}if(view==='tuner')openTuner();if(view==='map')openMap();if(view==='journal')openJournal();}
function openTuner(){modal('寻找雨里的声音','FREQUENCY SCANNER / FM',`<p>转动频率，留意信号强度。靠近清晰信号时，锁定并记下来。</p><div class="tuner-display"><strong id="frequency-value">${frequency.toFixed(1)}</strong><span> MHz</span><div class="tuner-scale"><span>87.0</span><span>89.0</span><span>91.0</span><span>93.0</span><span>95.0</span><span>97.0</span></div></div><input class="tuner-input" id="frequency-input" aria-label="调谐频率" type="range" min="87" max="97" value="${frequency}" step="0.1"><div class="signal-indicator"><span id="tuner-label">只有雨声</span><div class="signal-bar"><i id="tuner-strength"></i></div></div><div class="tuner-actions"><button class="secondary-button" id="scan-button">自动搜索附近信号</button><button class="primary-button" id="lock-frequency">${icon('signal')}锁定频率 · 电力 −3</button></div><div id="tuner-result"></div><div class="clue-list">${FREQUENCIES.map(f=>`<span class="clue-chip">${state.tuned.includes(f.freq)?'✓ '+f.freq+' · '+f.title:state.flags.includes('HINT_'+String(f.freq).replace('.',''))?f.freq+' MHz · 待收听':'??? MHz · 未知信号'}</span>`).join('')}</div>`);updateTuner();}
function updateTuner(){let distance=Math.min(...FREQUENCIES.map(f=>Math.abs(f.freq-frequency))),strength=Math.max(5,Math.round(100-distance*170));$('frequency-value').textContent=frequency.toFixed(1);$('tuner-strength').style.width=strength+'%';$('tuner-label').textContent=strength>82?'捕捉到人声 · 可以锁定':strength>35?'信号正在靠近…':'雨声与白噪音';audio.static(strength/100);}
function lockFrequency(){let result=tune(state,frequency);if(result.error){toast(result.error);return;}audio.success();render();openTuner();$('tuner-result').innerHTML=`<p class="lede">${result.repeat?'再次收听':'信号已记录'} · ${result.clue.title}</p><p>${result.clue.text}</p>`;}
const mapPoints=[{id:'station',name:'夜航电台',x:43,y:66,detail:'山坡上的一间直播室。今晚，你的声音是连接整座小镇的线。',flag:''},{id:'pier',name:'港口修理铺',x:16,y:72,detail:'阿岚还守在电话旁边。他修好的每一台收音机，都可能带回一个消息。',flag:'HINT_936'},{id:'lighthouse',name:'北岬灯塔',x:72,y:17,detail:'一束时明时暗的光。黄色扶手后，藏着通往三号井的备用梯。',flag:'ROUTE'},{id:'reservoir',name:'旧水库',x:34,y:23,detail:'十年前的事故没有被完整记录。安全步骤是救援的关键。',flag:'ORDER'},{id:'well',name:'北岸检修井',x:63,y:43,detail:'风雨吞没了入口。找到精确位置，才能把救援队带到正确的门前。',flag:'LOCATION'},{id:'street',name:'下街与学校',x:11,y:45,detail:'许真在便利店等你的安排。北坡学校比下街更安全。',flag:'EVAC_DONE'}];
function openMap(selected='station'){modal('雾港，仍有人醒着','WUGANG / 24 OCT 1997',`<div class="map-surface"><svg viewBox="0 0 600 300" aria-hidden="true"><path d="M60 250C140 230 130 160 240 185S350 225 440 125 500 70 560 20"/><path d="M80 155 220 210 390 140 430 55 M220 210 215 80 M215 80 430 55" stroke-dasharray="5 6"/><path d="M15 276C180 280 120 220 260 258S370 150 540 190" stroke="#55958b50" stroke-width="10"/></svg>${mapPoints.map(p=>`<button class="map-node ${p.id==='station'||state.flags.includes(p.flag)?'active':''} ${p.id===selected?'selected':''}" style="left:${p.x}%;top:${p.y}%" data-map="${p.id}"><i></i>${p.name}</button>`).join('')}</div><div class="map-detail" id="map-detail"></div><div class="clue-list">${['RESCUED','TRUTH_PUBLIC','EVAC_DONE'].map(f=>`<span class="clue-chip">${state.flags.includes(f)?'✓':'○'} ${FLAG_NAMES[f]}</span>`).join('')}</div>`);showMapPoint(selected);}
function showMapPoint(id){let p=mapPoints.find(p=>p.id===id);let extra=p.flag&&state.flags.includes(p.flag)?' 已记录相关线索。':'';if(id==='well'&&state.flags.includes('RESCUED'))extra=' 小满已经平安离开检修井。';if(id==='street'&&state.flags.includes('EVAC_DONE'))extra=' 下街居民已全部抵达学校。';$('map-detail').innerHTML=`<h3>${p.name}</h3><p>${p.detail}${extra}</p>`;document.querySelectorAll('.map-node').forEach(el=>el.classList.toggle('selected',el.dataset.map===id));}
function openJournal(){modal('记下那些没有说完的话','BROADCAST JOURNAL',`<div class="clue-list" style="margin-top:0;margin-bottom:25px">${Object.entries(FLAG_NAMES).filter(([k])=>state.flags.includes(k)).map(([k,v])=>`<span class="clue-chip">✓ ${v}</span>`).join('')||'<span class="clue-chip">尚未收集到线索</span>'}</div>${state.journal.length?state.journal.map(j=>`<article class="journal-entry"><time>${esc(j.time)}</time><h3>${esc(j.title)}</h3><p>${esc(j.text)}</p></article>`).join(''):'<div class="journal-empty"><p class="lede">今晚的第一句话，还在路上。</p><p>来电、广播、隐藏频率都会自动记在这里。</p></div>'}`);}
function openHelp(){modal('今晚，你是主持人','HOW TO PLAY',`<p class="lede">一间电台，一座小镇。把声音留到天亮。</p><p>没有倒计时。慢慢听、慢慢决定，夜晚只会在你继续时推进。</p><div class="help-grid"><div class="help-item">${icon('phone')}<h3>01 · 接听来电</h3><p>六位来电者带来线索。每个回应都会改变信任、信号或电力，代价会提前显示。</p></div><div class="help-item">${icon('mic')}<h3>02 · 决定播什么</h3><p>每通来电可广播一次。旧歌安抚情绪，证词公开真相，紧急通知引导居民。</p></div><div class="help-item">${icon('signal')}<h3>03 · 寻找隐藏声音</h3><p>扫描频率收集额外线索。点击配电箱，按正确顺序恢复备用电力。</p></div><div class="help-item">${icon('sun')}<h3>04 · 留下你的结局</h3><p>能否救回小满、留下证据，决定四种结局。下街疏散还有独立的故事尾声。</p></div></div><p>拖动查看房间，点击电话、收音机、麦克风、唱片机、笔记本与配电箱。快捷键：E 接听 · 1–4 切换面板 · 空格广播 · Esc 关闭。</p><button class="primary-button" data-action="close">我准备好了</button>`);}
function openSettings(){modal('调整你的夜晚','STUDIO SETTINGS',`<div class="settings-row"><div>环境声音<small>雨声、电话、模拟合成的钢琴旋律</small></div><button class="secondary-button" data-action="sound">${state.muted?'开启声音':'关闭声音'}</button></div><div class="settings-row"><div>总音量<small>建议戴上耳机，留一点音量给雨。</small></div><input id="volume-input" type="range" min="0" max="1" step=".05" value="${state.volume}" aria-label="总音量"></div><div class="settings-row"><div>备用电路<small>${state.repaired?'电路已修复':'配电箱在窗边，可以恢复 18 点电力。'}</small></div><button class="secondary-button" data-action="repair">检查电路</button></div><div class="settings-row"><div>重新开始<small>清除当前夜晚的进度，体验其他选择。</small></div><button class="secondary-button danger-button" data-action="restart-confirm">重新开播</button></div><p>进度保存在当前浏览器。来电语音使用设备提供的中文语音；没有中文语音时，可完整阅读字幕。</p>`);}
function openRepair(){repairSteps=[];modal('把最后一盏灯留住','BACKUP CIRCUIT',state.repaired?`<p class="lede">备用线路已经恢复。</p><p>这一夜的应急电池已接通。好好使用剩下的电力。</p>`:`<p>配电箱上贴着一张旧便签：</p><p class="lede">“先隔离回流，再接地线，最后合上主闸。”</p><p>按顺序检查三个开关。修复后恢复 18 点电力，每夜一次。</p><div class="help-grid" style="grid-template-columns:repeat(3,1fr)">${[{id:'main',label:'主闸'},{id:'return',label:'回流'},{id:'ground',label:'地线'}].map(f=>`<button class="secondary-button" data-fuse="${f.id}">${icon('battery')}<span>${f.label}</span></button>`).join('')}</div><p id="repair-progress">等待检查 · 0 / 3</p>`);}
function doRepair(id){let order=['return','ground','main'];if(id!==order[repairSteps.length]){repairSteps=[];$('repair-progress').textContent='顺序不对，保险保护已启动。请从回流重新检查。';document.querySelectorAll('[data-fuse]').forEach(el=>{el.disabled=false;el.style.borderColor='';});audio.tone(170,.2,.09);return;}repairSteps.push(id);const btn=document.querySelector(`[data-fuse="${id}"]`);btn.disabled=true;btn.style.borderColor='#bbca87';$('repair-progress').textContent=`线路检查中 · ${repairSteps.length} / 3`;audio.click();if(repairSteps.length===3&&repair(state)){render();audio.success();$('repair-progress').textContent='备用线路恢复，电力 +18。窗外的夜晚，似乎也亮了一点。';toast('备用电路已修复 · 电力 +18');}}
function openEnding(){let e=getEnding(state);modal('夜晚的回响','THANK YOU FOR STAYING',`<div class="ending"><div class="ending-tag">${e.tag}</div><div class="ending-symbol">☼</div><h3>${e.title}</h3><p class="lede">${e.text}</p><p>${state.flags.includes('EVAC_DONE')?'下街的人在学校点完了最后一个名字。收音机里，一首熟悉的歌仍在继续。':'天亮后，救援队仍在下街逐户敲门。人们记得，在最黑的夜里，有一台收音机一直亮着。'}</p><div class="ending-stats"><div><strong>${state.trust}</strong><small>小镇信任</small></div><div><strong>${state.tuned.length}/3</strong><small>隐藏频率</small></div><div><strong>${state.journal.filter(j=>PROGRAMS.some(p=>p.title===j.title)).length}</strong><small>播出的节目</small></div></div><p>四种结局，许多未说完的故事。下一次，你会把声音留给谁？</p><button class="primary-button" data-action="restart-confirm">再主持一个夜晚</button><button class="secondary-button" data-action="journal">翻阅本夜日志</button></div>`);}
function restartConfirm(){modal('重新开播？','A NEW NIGHT',`<p>这一夜的来电、线索和广播记录会被清除。新的夜晚，将从 00:07 开始。</p><div class="tuner-actions"><button class="secondary-button" data-action="close">留在这一夜</button><button class="primary-button" data-action="restart">确认重新开始</button></div>`);}
function restart(){let volume=state.volume,muted=state.muted;state={...initialState(),volume,muted};audio.stopSpeech();audio.stopMusic();closeModal();studio?.dispose();$('scene').innerHTML='';bootScene();render();toast('00:07 · 夜航电台，重新为你开播。');}
function interact(action){audio.init();audio.click();if(action==='phone'){closeModal();if(state.phase==='ringing')answer();else if(state.phase==='ended')openEnding();else toast('来电内容和回应选项在右侧。');}if(action==='tuner')selectView('tuner');if(action==='music'){state.selected='music';render();doBroadcast();}if(action==='journal')selectView('journal');if(action==='broadcast'){closeModal();$('broadcast-button').focus();toast('选择想要播出的内容，再开始广播。');}if(action==='repair')openRepair();if(action==='lamp')toast(studio?.toggleLamp()?'台灯亮了。这个夜晚，还有人守着。':'台灯已关闭，窗外的灯火更清晰了。');}
function bootScene(){try{studio=createStudio($('scene'),interact);}catch(err){console.error('3D scene initialization failed:',err);studio=null;$('scene').innerHTML='<div class="scene-fallback">当前浏览器未能启动 3D 画面。来电、调频与所有故事功能仍可使用。可尝试在支持 WebGL 的浏览器打开。</div>';}}
document.addEventListener('click',e=>{let target=e.target.closest('button');if(!target)return;if(target.dataset.view)selectView(target.dataset.view);if(target.dataset.program){state.selected=target.dataset.program;audio.click();render();}if(target.dataset.choice!==undefined)chooseOption(Number(target.dataset.choice));if(target.dataset.map)showMapPoint(target.dataset.map);if(target.dataset.fuse)doRepair(target.dataset.fuse);let action=target.dataset.action;if(action==='answer')answer();if(action==='next')nextCall();if(action==='ending')openEnding();if(action==='close')closeModal();if(action==='sound'){setSound();openSettings();}if(action==='repair')openRepair();if(action==='restart-confirm')restartConfirm();if(action==='restart')restart();if(action==='journal')selectView('journal');if(action==='read-call'){if(state.muted){state.muted=false;audio.init();audio.set(false,state.volume);render();}audio.speak(currentCall().text);}if(target.id==='scan-button'){let nextFreq=FREQUENCIES.find(f=>f.freq>frequency+.15)||FREQUENCIES[0];frequency=nextFreq.freq;$('frequency-input').value=frequency;updateTuner();}if(target.id==='lock-frequency')lockFrequency();});
document.addEventListener('input',e=>{if(e.target.id==='frequency-input'){frequency=Number(e.target.value);updateTuner();}if(e.target.id==='volume-input'){state.volume=Number(e.target.value);audio.set(state.muted,state.volume);persist();}});
$('broadcast-button').addEventListener('click',doBroadcast);$('sound-button').addEventListener('click',setSound);$('help-button').addEventListener('click',openHelp);$('settings-button').addEventListener('click',openSettings);$('close-modal').addEventListener('click',closeModal);$('modal').addEventListener('click',e=>{if(e.target===$('modal'))closeModal();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();audio.stopSpeech();return;}if(!$('modal').hidden){if(e.key==='Tab'){const focusables=[...$('modal').querySelectorAll('button:not(:disabled),input')],first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}if(['INPUT','TEXTAREA'].includes(e.target.tagName)||e.repeat)return;if(e.code==='Space'&&e.target.tagName!=='BUTTON'){e.preventDefault();doBroadcast();}if(e.key.toLowerCase()==='e')answer();if(['1','2','3','4'].includes(e.key))selectView(['studio','tuner','map','journal'][Number(e.key)-1]);});
icons();bootScene();render();setTimeout(()=>{$('loading').style.opacity='0';setTimeout(()=>$('loading').remove(),720);},700);
